const THREE=window.THREE;
(async function(){
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={meta:null,data:null,labels:null,position:[0,0,0],job:null,sequence:'T1',auto:false,planes:false,meshes:{},layers:{brain:{name:'Brain surface',color:'#a7bed7',opacity:.2,visible:true},WT:{name:'Whole tumour',detail:'WT',color:'#75d0b0',opacity:.28,visible:true},TC:{name:'Tumour core',detail:'TC',color:'#f0b66f',opacity:.55,visible:true},ET:{name:'Enhancing tumour',detail:'ET',color:'#e98391',opacity:.9,visible:true}}};
let scene,camera,renderer,root,marker,planeGroup,phi=1.05,theta=.50,distance=295,pan=[0,0],service=false;
function corticalMaterial(opacity){return new THREE.ShaderMaterial({uniforms:{alpha:{value:opacity}},vertexShader:'varying vec3 n; varying vec3 v; void main(){vec4 p=modelViewMatrix*vec4(position,1.0); n=normalize(normalMatrix*normal); v=-p.xyz; gl_Position=projectionMatrix*p;}',fragmentShader:'uniform float alpha; varying vec3 n; varying vec3 v; void main(){vec3 N=normalize(n); float rim=pow(1.0-abs(dot(N,normalize(v))),1.7); float light=0.45+0.55*abs(dot(N,normalize(vec3(0.4,0.8,0.5)))); gl_FragColor=vec4(vec3(0.51,0.65,0.79)*light,alpha*(0.06+0.85*rim));}',transparent:true,depthWrite:false,side:THREE.FrontSide})}
const toast=t=>{$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)};
function modal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal').showModal()}
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').close()};
function init3D(){const el=$('#stage');scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(35,1,.1,3000);renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0,0);el.prepend(renderer.domElement);scene.add(new THREE.AmbientLight(0xa4c6ed,.4));for(const [pos,color,power] of [[[150,220,100],0xd9e9ff,.75],[[-150,0,-90],0x7195c5,.3],[[0,-100,150],0xb6c4de,.15]]){const l=new THREE.DirectionalLight(color,power);l.position.set(...pos);scene.add(l)}root=new THREE.Group();scene.add(root);marker=new THREE.Mesh(new THREE.SphereGeometry(1.3,16,16),new THREE.MeshBasicMaterial({color:0xb4d8ff,depthTest:false}));marker.renderOrder=10;root.add(marker);planeGroup=new THREE.Group();root.add(planeGroup);const resize=()=>{const w=el.clientWidth,h=el.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()};new ResizeObserver(resize).observe(el);let drag=null;renderer.domElement.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,shift:e.shiftKey};renderer.domElement.setPointerCapture(e.pointerId)};renderer.domElement.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(drag.shift){pan[0]-=dx*.2;pan[1]+=dy*.2}else{phi-=dx*.008;theta=Math.max(-1.35,Math.min(1.35,theta+dy*.008));state.auto=false;$('#rotate').classList.remove('selected')}drag.x=e.clientX;drag.y=e.clientY};renderer.domElement.onpointerup=()=>drag=null;renderer.domElement.onwheel=e=>{e.preventDefault();distance=Math.max(130,Math.min(650,distance+e.deltaY*.2))};function animate(){requestAnimationFrame(animate);if(state.auto)phi+=.002;camera.position.set(Math.sin(phi)*Math.cos(theta)*distance+pan[0],Math.sin(theta)*distance+pan[1],Math.cos(phi)*Math.cos(theta)*distance);camera.lookAt(pan[0],pan[1],0);renderer.render(scene,camera)}animate()}
function loadMeshes(json){for(const m of Object.values(state.meshes)){root.remove(m);m.geometry.dispose();m.material.dispose()}state.meshes={};for(const [key,value] of Object.entries(json)){const l=state.layers[key];if(!l)continue;const g=new THREE.BufferGeometry();const v=new Float32Array(value.vertices);for(let i=0;i<v.length;i+=3){const y=v[i+1],z=v[i+2];v[i+1]=z;v[i+2]=-y-20}g.setAttribute('position',new THREE.BufferAttribute(v,3));g.setIndex(value.indices);g.computeVertexNormals();const material=key==='brain'?corticalMaterial(l.opacity):new THREE.MeshPhongMaterial({color:l.color,specular:0x080808,transparent:true,opacity:l.opacity,shininess:key==='brain'?55:35,side:key==='brain'?THREE.FrontSide:THREE.DoubleSide,depthWrite:key!=='brain'});const m=new THREE.Mesh(g,material);m.visible=l.visible;m.renderOrder=key==='brain'?4:key==='WT'?3:key==='TC'?2:1;root.add(m);state.meshes[key]=m}$('#anatomy-status').textContent=state.meta.demo?'Reference anatomy · synthetic regions':'Input-derived anatomy · model prediction';}
function affine(p){return state.meta.affine.slice(0,3).map(r=>r[0]*p[0]+r[1]*p[1]+r[2]*p[2]+r[3])}
function updatePosition(){const p=state.position,w=affine(p);$('#voxel').textContent=p.join(' , ');$('#world').textContent=w.map(v=>v.toFixed(1)).join(' , ')+' mm';marker?.position.set(w[0],w[2],-w[1]-20);if(planeGroup){while(planeGroup.children.length){const c=planeGroup.children[0];planeGroup.remove(c);c.geometry.dispose();c.material.dispose()}if(state.planes){for(let a=0;a<3;a++){const points=[];for(let d of [-100,100]){const q=[w[0],w[2],-w[1]-20];q[a]+=d;points.push(new THREE.Vector3(...q))}planeGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineBasicMaterial({color:0x7ca5db,transparent:true,opacity:.7,depthTest:false})))}}}drawSlices()}
const configs=[{name:'Axial',axis:2,u:0,v:1,ends:['A','P','L','R']},{name:'Coronal',axis:1,u:0,v:2,ends:['S','I','L','R']},{name:'Sagittal',axis:0,u:1,v:2,ends:['S','I','P','A']}];
function setupSlices(){const sh=state.meta.shape;$('#slices').innerHTML=configs.map((c,i)=>`<div class="slice"><div class="slice-title"><strong>${c.name}</strong><span id="slice-label-${i}"></span></div><div class="slice-display"><canvas id="slice-${i}" aria-label="${c.name} MRI slice. Click to move the shared crosshair."></canvas>${['top','bottom','left','right'].map((k,j)=>`<span class="orientation-label ${k}">${c.ends[j]}</span>`).join('')}</div><input aria-label="${c.name} slice index" type="range" min="0" max="${sh[c.axis]-1}" id="slider-${i}"></div>`).join('');configs.forEach((c,i)=>{const slider=$(`#slider-${i}`);slider.oninput=()=>{state.position[c.axis]=Number(slider.value);updatePosition()};const can=$(`#slice-${i}`);can.onclick=e=>{const r=can.getBoundingClientRect(),ratio=can.width/can.height;let w=r.width,h=r.height;if(w/h>ratio)w=h*ratio;else h=w/ratio;const ox=(r.width-w)/2,oy=(r.height-h)/2;state.position[c.u]=Math.max(0,Math.min(sh[c.u]-1,Math.round((e.clientX-r.left-ox)/w*(sh[c.u]-1))));state.position[c.v]=Math.max(0,Math.min(sh[c.v]-1,Math.round((1-(e.clientY-r.top-oy)/h)*(sh[c.v]-1))));updatePosition()};can.onwheel=e=>{e.preventDefault();state.position[c.axis]=Math.max(0,Math.min(sh[c.axis]-1,state.position[c.axis]+Math.sign(e.deltaY)));updatePosition()}})}
function drawSlices(){if(!state.data)return;const shape=state.meta.shape,sp=state.meta.spacing;configs.forEach((c,i)=>{const w=shape[c.u],h=shape[c.v],can=$(`#slice-${i}`);can.width=w;can.height=h;can.style.aspectRatio=`${w*sp[c.u]}/${h*sp[c.v]}`;const ctx=can.getContext('2d'),img=ctx.createImageData(w,h);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const p=[...state.position];p[c.u]=x;p[c.v]=h-1-y;const idx=p[0]+shape[0]*(p[1]+shape[1]*p[2]),d=(x+w*y)*4;let g=state.data[idx]??0;img.data[d]=img.data[d+1]=img.data[d+2]=g;img.data[d+3]=255;const label=state.labels?.[idx]??0;let key=label===4?'ET':label===1?'TC':label===2?'WT':null;if(key&&!state.layers[key].visible){key=state.layers.WT.visible?'WT':null}if(key){const l=state.layers[key],hex=l.color;const blend=Math.max(.15,l.opacity*.65);for(let j=0;j<3;j++)img.data[d+j]=g*(1-blend)+parseInt(hex.slice(1+j*2,3+j*2),16)*blend}}ctx.putImageData(img,0,0);const px=state.position[c.u]+.5,py=h-1-state.position[c.v]+.5;ctx.strokeStyle='#91c3eeaa';ctx.lineWidth=.55;ctx.beginPath();ctx.moveTo(px,0);ctx.lineTo(px,py-4);ctx.moveTo(px,py+4);ctx.lineTo(px,h);ctx.moveTo(0,py);ctx.lineTo(px-4,py);ctx.moveTo(px+4,py);ctx.lineTo(w,py);ctx.stroke();$(`#slider-${i}`).value=state.position[c.axis];$(`#slice-label-${i}`).textContent=`${['X','Y','Z'][c.axis]} = ${state.position[c.axis]} / ${shape[c.axis]-1}`})}
function layers(){ $('#layers').innerHTML=Object.entries(state.layers).map(([key,l])=>`<div class="layer" style="--c:${l.color}"><span class="swatch"></span><span>${l.name}<small>${l.detail||'ANATOMY'}</small></span><input aria-label="${l.name} opacity" data-layer="${key}" type="range" value="${Math.round(l.opacity*100)}" min="0" max="100"><span class="percent">${Math.round(l.opacity*100)}%</span><button class="toggle ${l.visible?'on':''}" aria-label="Toggle ${l.name}" aria-pressed="${l.visible}" data-toggle="${key}"></button></div>`).join('');$$('[data-layer]').forEach(el=>el.oninput=()=>{const l=state.layers[el.dataset.layer];l.opacity=Number(el.value)/100;el.nextElementSibling.textContent=el.value+'%';if(state.meshes[el.dataset.layer])state.meshes[el.dataset.layer].material.opacity=l.opacity;if(state.meshes[el.dataset.layer]?.material.uniforms?.alpha)state.meshes[el.dataset.layer].material.uniforms.alpha.value=l.opacity;drawSlices()});$$('[data-toggle]').forEach(el=>el.onclick=()=>{const l=state.layers[el.dataset.toggle];l.visible=!l.visible;el.classList.toggle('on',l.visible);el.setAttribute('aria-pressed',String(l.visible));if(state.meshes[el.dataset.toggle])state.meshes[el.dataset.toggle].visible=l.visible;drawSlices()})}
function measurements(){ $('#metrics').innerHTML=['WT','TC','ET'].map((key,i)=>{const l=state.layers[key],r=state.meta.regions[key];return `<article class="metric" style="--c:${l.color}"><div class="metric-title"><span class="swatch"></span>${l.name} <span class="muted">(${key})</span></div><div class="metric-bar">${[7,13,9,20,15].map(h=>`<i style="height:${h}px"></i>`).join('')}</div><div class="metric-value">${r.volume_ml.toFixed(2)}<span>mL</span></div><div class="metric-line"><span>${state.meta.demo?'SYNTHETIC REGION':'MODEL ESTIMATE'}</span><b>${r.voxel_count.toLocaleString()} voxels</b></div></article>`}).join('')}
async function loadReference(){const [meta,bin,lab,mesh]=await Promise.all([fetch('assets/reference.json').then(r=>r.json()),fetch('assets/reference.bin').then(r=>r.arrayBuffer()),fetch('assets/labels.bin').then(r=>r.arrayBuffer()),fetch('assets/meshes.json').then(r=>r.json())]);state.meta=meta;state.data=new Uint8Array(bin);state.labels=new Uint8Array(lab);state.position=meta.shape.map(v=>Math.floor(v/2));state.position=[Math.round((27-meta.affine[0][3])/meta.affine[0][0]),Math.round((-20-meta.affine[1][3])/meta.affine[1][1]),Math.round((25-meta.affine[2][3])/meta.affine[2][2])];loadMeshes(mesh);setupSlices();measurements();updatePosition()}
$('#reset').onclick=()=>{phi=1.05;theta=.50;distance=295;pan=[0,0]};$('#rotate').onclick=()=>{state.auto=!state.auto;$('#rotate').classList.toggle('selected',state.auto)};$('#rotate').classList.remove('selected');$('#zoomIn').onclick=()=>distance=Math.max(130,distance-25);$('#zoomOut').onclick=()=>distance=Math.min(650,distance+25);$('#planes').onclick=()=>{state.planes=!state.planes;$('#planes').classList.toggle('selected',state.planes);updatePosition()};$('#fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else $('.twin-panel').requestFullscreen()};$('#center').onclick=()=>{state.position=state.meta.shape.map(v=>Math.floor(v/2));updatePosition()};
$$('[data-seq]').forEach(b=>b.onclick=async()=>{const seq=b.dataset.seq;if(state.meta.demo&&seq!=='T1'){toast('The reference demo contains T1 only. Import four sequences in the local app to switch modalities.');return}if(state.job){const r=await fetch(`/api/jobs/${state.job}/volume/${seq}`);if(!r.ok)return toast('This sequence could not be loaded.');state.data=new Uint8Array(await r.arrayBuffer())}state.sequence=seq;$$('[data-seq]').forEach(x=>x.classList.toggle('active',x===b));drawSlices()});
$('#formula').onclick=()=>modal('Volume, with the working shown',`<p class="modal-copy">Volume = region voxel count × physical voxel volume ÷ 1,000.<br>Physical voxel volume = |det(affine₃×₃)|. This also handles rotated and sheared grids.</p><div class="info-card"><table><tr><th>Region</th><th>Voxels</th><th>Voxel volume</th><th>Estimated volume</th></tr>${['WT','TC','ET'].map(k=>`<tr><td>${k}</td><td>${state.meta.regions[k].voxel_count}</td><td>${(state.meta.regions[k].voxel_volume_mm3??Math.abs(det3(state.meta.affine))).toFixed(4)} mm³</td><td>${state.meta.regions[k].volume_ml.toFixed(3)} mL</td></tr>`).join('')}</table></div><p class="modal-copy">${state.meta.demo?'These teaching regions are synthetic. No model accuracy or uncertainty is implied.':'These are suspected tumour regions predicted by the model, not a diagnosis.'}</p>`);
function det3(a){return a[0][0]*(a[1][1]*a[2][2]-a[1][2]*a[2][1])-a[0][1]*(a[1][0]*a[2][2]-a[1][2]*a[2][0])+a[0][2]*(a[1][0]*a[2][1]-a[1][1]*a[2][0])}
function page(p){$('#workspace').hidden=p!=='workspace';$('#info-page').hidden=p==='workspace';$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));if(p==='workspace')return;const m=state.meta;let html='';if(p==='studies'){html=`<h2>Study information</h2><p>${m.name}. ${m.description||''}</p><table><tr><th>Property</th><th>Value</th></tr><tr><td>Mode</td><td>${m.demo?'Illustrative demo · no model executed':'Live inference · local processing'}</td></tr><tr><td>Viewer grid</td><td>${m.shape.join(' × ')} voxels, canonical RAS+</td></tr><tr><td>Spacing</td><td>${m.spacing.map(v=>v.toFixed(4)).join(' × ')} mm</td></tr><tr><td>Original-grid export</td><td>${m.demo?'Unavailable for synthetic demo':'Preserved · NIfTI labels 0, 1, 2, 4'}</td></tr><tr><td>Expert annotation</td><td>${m.expert?'Provided; measured in report':'Not provided'}</td></tr></table><h3>Voxel-to-world affine</h3><pre>${m.affine.map(r=>r.map(v=>v.toFixed(4).padStart(10)).join(' ')).join('\n')}</pre><p>Viewer images and meshes share this physical coordinate system. Live output is saved on the original input grid.</p>${state.job?'<button id="download-mask" class="button primary">Download predicted NIfTI</button>':''}`;}else if(p==='evidence'){html=`<h2>Model & evidence</h2><p>Confidence starts with knowing what has actually been measured.</p><table><tr><th>Item</th><th>Status</th></tr><tr><td>Architecture</td><td>MONAI SegResNet · brats_mri_segmentation</td></tr><tr><td>Model licence</td><td>Apache-2.0 · MONAI Consortium</td></tr><tr><td>Training source</td><td>BraTS 2018; model card reports 200 training studies</td></tr><tr><td>Input order</td><td>T1Gd, T1, T2, FLAIR · 1 mm grid · nonzero channel normalization</td></tr><tr><td>Region outputs</td><td>TC, WT, ET; sigmoid threshold 0.5</td></tr><tr><td>This project's held-out evaluation</td><td>Not performed. Organiser-approved labelled cases are needed.</td></tr><tr><td>Pretraining overlap</td><td>Unverified. Do not treat evaluation as independent until audited.</td></tr><tr><td>Uncertainty</td><td>Not implemented. No calibrated confidence percentage is reported.</td></tr><tr><td>T4 end-to-end timing</td><td>Not benchmarked</td></tr></table><h3>Interpretation limits</h3><p>The model expects co-registered, skull-stripped adult glioma MRI. Other anatomy, acquisition protocols, unstripped inputs and artefacts may produce unreliable outputs. Input checks are conservative heuristics and cannot certify anatomy. Region estimates do not diagnose disease or guide treatment.</p><h3>Reproducible output</h3><p>Local runs record input SHA-256 hashes, checkpoint hash, software versions, spatial transforms, runtime and timestamp. The output mapping follows the <a href="https://huggingface.co/MONAI/brats_mri_segmentation/blob/main/configs/inference.json" target="_blank" rel="noreferrer">official MONAI inference configuration</a>: ET → 4, remaining TC → 1, remaining WT → 2.</p><p><a href="https://huggingface.co/MONAI/brats_mri_segmentation/blob/main/docs/README.md" target="_blank" rel="noreferrer">Read the source model card ↗</a> · <a href="https://doi.org/10.7937/jc8x-9874" target="_blank" rel="noreferrer">BraTS 2021 data credit ↗</a></p>`;}else{html=`<h2>Your imaging workspace</h2><h3>Explore the digital twin</h3><p>Drag to rotate; scroll to zoom; Shift + drag to pan. Reset returns to the initial viewpoint. Each anatomy or region layer has its own visibility toggle and opacity slider. The crosshair button draws linked position axes in 3D.</p><h3>Inspect linked slices</h3><p>Click a slice to move the shared crosshair. Scroll over a slice or use its slider to step through the volume. Voxel indices and physical millimetres update together. The local service canonicalizes viewer volumes to RAS+; label exports preserve the original grid and affine.</p><h3>Run a real study</h3><p>Start the supplied local platform, open its local address, import four NIfTI sequences, then run segmentation. A locally installed, verified MONAI checkpoint is required. The hosted reference workspace does not upload MRI scans to a cloud service.</p><h3>Read results responsibly</h3><p>Estimated volume is a measurement of a predicted mask. Dice and sensitivity require expert labels; they cannot be inferred from a scan alone. The reference demo uses public anatomy and synthetic regions to demonstrate interaction only.</p>`}$('#info-page').innerHTML=`<article class="panel info-card">${html}<p class="muted">Research and teaching only. Never use model output as a diagnosis.</p><button class="button secondary" id="back">← Back to workspace</button></article>`;$('#back').onclick=()=>page('workspace');if($('#download-mask'))$('#download-mask').onclick=()=>location.href=`/api/jobs/${state.job}/prediction`}
$$('[data-page]').forEach(b=>b.onclick=()=>page(b.dataset.page));$('#details').onclick=()=>page('studies');
$('#upload').onclick=()=>{modal('Import a research study',`<p class="modal-copy">Provide four co-registered, skull-stripped, public research MRI volumes. Each file must be a nonconstant, finite, 3D NIfTI (.nii or .nii.gz), at most 1 GB.</p>${!service?'<div class="error">The local inference service is not connected. Open the supplied local platform to process scans. Files selected here will not be transmitted.</div>':''}${['T1','T1Gd','T2','FLAIR','Expert'].map(s=>`<label class="upload-row"><span>${s}${s==='Expert'?' (opt.)':''}</span><input id="file-${s}" type="file" accept=".nii,.nii.gz"></label>`).join('')}<p class="modal-copy">Expert labels: 0 background, 1 NCR, 2 ED, 4 ET. All volumes must share shape and affine.</p><label class="modal-copy"><input type="checkbox" id="consent"> I confirm these are public, de-identified research data.</label><div class="modal-actions"><button id="run" class="button primary">Validate & run segmentation</button><button id="restore" class="button secondary">Use reference demo</button></div><div id="upload-status" role="status"></div>`);$('#restore').onclick=()=>{$('#modal').close();location.reload()};$('#run').onclick=runStudy};
async function runStudy(){const status=$('#upload-status');status.innerHTML='';const fail=t=>status.innerHTML=`<div class="error">${t}</div>`;if(!$('#consent').checked)return fail('Confirm that the study is public and de-identified before continuing.');const form=new FormData();for(const s of ['T1','T1Gd','T2','FLAIR']){const f=$(`#file-${s}`).files[0];if(!f)return fail(`Missing ${s}. Please select all four sequences.`);if(f.size>1e9)return fail(`${s} exceeds the 1 GB limit.`);if(!/\.nii(\.gz)?$/i.test(f.name))return fail(`${s} must be a .nii or .nii.gz file.`);form.append(s,f)}const expert=$('#file-Expert').files[0];if(expert){if(expert.size>1e9)return fail('Expert mask exceeds the 1 GB limit.');form.append('expert',expert)}if(!service)return fail('Open the local platform to run this study. No files were uploaded.');$('#run').disabled=true;status.innerHTML='<p class="modal-copy">Validating files and running the local model. This can take several minutes on CPU…</p>';try{const r=await fetch('/api/segment',{method:'POST',body:form});const result=await r.json();if(!r.ok)throw Error(typeof result.detail==='string'?result.detail:result.detail?.message||'The study could not be processed.');const id=result.job_id;const [meta,bin,lab,mesh]=await Promise.all([fetch(`/api/jobs/${id}/metadata`).then(r=>r.json()),fetch(`/api/jobs/${id}/volume/T1`).then(r=>r.arrayBuffer()),fetch(`/api/jobs/${id}/labels`).then(r=>r.arrayBuffer()),fetch(`/api/jobs/${id}/meshes`).then(r=>r.json())]);state.meta=meta;state.predLabels=new Uint8Array(lab);state.predMeshes=mesh;state.data=new Uint8Array(bin);state.labels=state.predLabels;state.job=id;state.sequence='T1';document.querySelectorAll('[data-seq]').forEach(el=>el.classList.toggle('active',el.dataset.seq==='T1'));document.querySelector('#compare-expert')?.remove();state.position=meta.shape.map(v=>Math.floor(v/2));loadMeshes(mesh);setupSlices();measurements();updatePosition();$('#study-name').textContent=meta.name;$('#study-sub').textContent='Locally processed · suspected tumour regions predicted by the model';$('#mode-badge').textContent='LIVE MODEL OUTPUT';$('#seq-count').textContent='4 / 4 aligned';$('#quality-text').textContent=meta.warnings.join(' ')||'Input checks passed. Model uncertainty has not been measured.';$('#readiness').textContent='Original-grid NIfTI & report available';$('#modal').close();page('workspace');toast('Segmentation completed. Review input warnings and limitations before interpreting results.')}catch(e){fail(e.message)}finally{if($('#run'))$('#run').disabled=false}}
$('#report').onclick=()=>{if(state.job){window.open(`/api/jobs/${state.job}/report`,'_blank');return}const m=state.meta;const content=`<!doctype html><html><head><title>NeuroSeg teaching report</title><style>body{font:15px system-ui;max-width:820px;margin:50px auto;padding:20px;color:#172538}h1{font-size:30px}table{width:100%;border-collapse:collapse}td,th{padding:12px;text-align:left;border-bottom:1px solid #ccc}p{line-height:1.7}.note{padding:18px;background:#edf2f8}button{padding:10px 16px}@media print{button{display:none}}</style></head><body><h1>NeuroSeg research report</h1><p class="note"><b>Illustrative demonstration only.</b> Public MNI152 reference anatomy with synthetic teaching regions. No model was run. These figures are not clinical measurements or model predictions.</p><p>Generated: ${new Date().toISOString()}</p><table><tr><th>Region</th><th>Voxels</th><th>Synthetic volume</th></tr>${['WT','TC','ET'].map(k=>`<tr><td>${k}</td><td>${m.regions[k].voxel_count}</td><td>${m.regions[k].volume_ml.toFixed(3)} mL</td></tr>`).join('')}</table><p>Volume = voxel count × ${Math.abs(det3(m.affine)).toFixed(6)} mm³ / 1,000.</p><p>Model execution: none. Accuracy: not measured. Uncertainty: not measured. Expert annotation: none. Input hashes: not applicable to this synthetic demonstration.</p><p>Reference anatomy source: <a href="${m.source}">NiiVue public demonstration MRI</a>. The teaching regions are generated independently for interaction testing and do not represent findings in this anatomy.</p><p><b>Research and teaching only. Never use model output as a diagnosis.</b></p><button onclick="print()">Print / Save as PDF</button></body></html>`;const url=URL.createObjectURL(new Blob([content],{type:'text/html'}));window.open(url,'_blank');setTimeout(()=>URL.revokeObjectURL(url),60000)};
function addExpertControl(){
 if($('#compare-expert'))return;
 const b=document.createElement('button');b.id='compare-expert';b.className='button secondary';b.textContent='Compare expert annotation';$('.metrics-heading').append(b);
 let active=false;
 b.onclick=async()=>{try{
  active=!active;
  if(active){
   const [binary,mesh]=await Promise.all([fetch(`/api/jobs/${state.job}/expert-labels`).then(r=>r.arrayBuffer()),fetch(`/api/jobs/${state.job}/expert-meshes`).then(r=>r.json())]);
   state.labels=new Uint8Array(binary);loadMeshes({brain:state.predMeshes.brain,...mesh});
  }else{state.labels=state.predLabels;loadMeshes(state.predMeshes)}
  b.textContent=active?'Viewing expert · show prediction':'Compare expert annotation';
  $('#anatomy-status').textContent=active?'Expert annotation · same physical grid':'Input-derived anatomy · model prediction';drawSlices();
 }catch{toast('Expert annotation could not be loaded.')}};
 const cards=$$('#metrics .metric');['WT','TC','ET'].forEach((key,i)=>{
  const e=document.createElement('div');e.className='metric-line';e.textContent=`Expert ${state.meta.expert[key].volume_ml.toFixed(2)} mL · Dice ${state.meta.metrics[key].dice.toFixed(3)} · Sens. ${state.meta.metrics[key].sensitivity===null?'n/a':state.meta.metrics[key].sensitivity.toFixed(3)}`;cards[i].append(e);
 });
}
try{init3D();layers();await loadReference()}catch(e){$('#anatomy-status').textContent='Viewer could not load';toast('The 3D viewer needs WebGL2. '+e.message)}
try{const r=await fetch('/api/health');if(r.ok){const h=await r.json();service=true;$('#service').textContent=h.model_ready?'Local model ready':'Local service · checkpoint needed';$('#readiness').textContent=h.model_ready?'Local inference service ready':'Local service needs a verified checkpoint'}}catch{}

})();
